describe('Password Reset Confirmation Message', () => {
  beforeEach(() => {
    cy.visit('/password-reset');
  });

  it('should display success confirmation message after successful password reset', () => {
    // Intercept the password reset API call
    cy.intercept('POST', '/api/auth/reset-password').as('resetPassword');

    // Fill in the reset form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="new-password-input"]').type('NewSecurePassword123!');
    cy.get('[data-testid="confirm-password-input"]').type('NewSecurePassword123!');

    // Submit the form
    cy.get('[data-testid="reset-password-button"]').click();

    // Wait for the API response
    cy.wait('@resetPassword');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Password reset successfully');

    // Verify reset link is visible
    cy.get('[data-testid="reset-link"]').should('be.visible');
    cy.get('[data-testid="reset-link"]').should('contain', 'Reset Password');

    // Verify email confirmation link is present
    cy.get('[data-testid="email-confirmation-link"]').should('be.visible');
    cy.get('[data-testid="email-confirmation-link"]').should('contain', 'Confirm Password Reset');
  });

  it('should not display success message if password reset fails', () => {
    // Intercept the password reset API call with a failure response
    cy.intercept('POST', '/api/auth/reset-password', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('resetPasswordFail');

    // Fill in the reset form
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="new-password-input"]').type('WeakPassword123');
    cy.get('[data-testid="confirm-password-input"]').type('WeakPassword123');

    // Submit the form
    cy.get('[data-testid="reset-password-button"]').click();

    // Wait for the failed API response
    cy.wait('@resetPasswordFail');

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Password reset failed');

    // Verify success message does not appear
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Verify reset link is not visible
    cy.get('[data-testid="reset-link"]').should('not.exist');

    // Verify email confirmation link is not visible
    cy.get('[data-testid="email-confirmation-link"]').should('not.exist');
  });
});
